function validate([arr, difference]) {
  if (arr.length < 1 || arr.length > 100000) return 'arr needs 1 to 100000 values.';
  if (arr.some(v => !Number.isInteger(v) || v < -10000 || v > 10000)) return 'Each value of arr is an integer between -10000 and 10000.';
  if (!Number.isInteger(difference) || difference < -10000 || difference > 10000) return 'difference is an integer between -10000 and 10000.';
  return null;
}

