function longestSubsequence(arr, difference) {
  const dp = new Map();
  let best = 0;

  for (const value of arr) {
    const previous = dp.get(value - difference) ?? 0;
    const length = previous + 1;
    dp.set(value, length);
    best = Math.max(best, length);
  }
  return best;
}

