function longestSubsequence(arr, difference) {
  const ending = [];
  let best = 0;
  for (let i = 0; i < arr.length; i++) {
    ending[i] = 1;
    for (let j = 0; j < i; j++) {
      if (arr[i] - arr[j] === difference) ending[i] = Math.max(ending[i], ending[j] + 1);
    }
    best = Math.max(best, ending[i]);
  }
  return best;
}

