function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const n = 2000;
    const span = [20, 300, 10000][pick(0, 2)];
    const difference = rand() < 0.5 ? pick(-5, 5) : pick(-span, span);
    const arr = [];
    let current = pick(-span, span);
    for (let i = 0; i < n; i++) {
      if (rand() < 0.4 && current + difference >= -10000 && current + difference <= 10000) {
        current += difference;
        arr.push(current);
      } else {
        arr.push(pick(-span, span));
      }
    }
    return [arr, difference];
  }
  const n = pick(1, 10);
  const arr = Array.from({ length: n }, () => pick(-5, 5));
  const difference = rand() < 0.1 ? pick(-10000, 10000) : pick(-3, 3);
  return [arr, difference];
}
